from pathlib import Path
import json,sys
R=Path(__file__).resolve().parents[1];A=R/'migrations/shared-nms002-l02-p048/audit'
clock=json.loads((A/'source-audio-clock-audit-v1.json').read_text());tails=json.loads((A/'source-feedback-tail-audit-v1.json').read_text())
assert clock['sourceSha256']==tails['sourceSha256']=='18786203d58efb8aa54c3701e72838887d0702ff03d68819830938a252facce7'
by={r['domain']:r for r in clock['streams']};tailBy={r['domain']:r for r in tails['rows']};rate=22050
fixed={'intro':{'domain':'498','start':0,'end':round(329*rate/12)},'continuation':{'domain':'498','start':round(329*rate/12),'end':by['sprite-498']['segments'][-1]['outputEnd']},'correct-feedback':{'domain':'442','start':by['sprite-442']['segments'][0]['outputStart'],'end':by['sprite-442']['segments'][-1]['outputEnd']}}
wrong=[];branches=by['sprite-444']['branches']
for i,b in enumerate(branches):
 start=round((b['firstFrame']-1)*rate/12);returned=round((b['returnFrame']-1)*rate/12);fullEnd=round((branches[i+1]['firstFrame']-1)*rate/12) if i+1<len(branches) else by['sprite-444']['segments'][-1]['outputEnd'];tail=next(t for t in tailBy['sprite-444']['tails'] if t['label']==b['label']);end=returned if tail['peak']==0 else fullEnd;assert start<returned<=end<=fullEnd
 wrong.append({'domain':'444','label':b['label'],'start':start,'end':end,'authoredReturn':returned,'silentTailOmitted':end<fullEnd})
short={}
for ident in ['8','413','436']:
 t=tailBy['sprite-'+ident]['tails'][0];assert t['peak']==0;short[ident]={'domain':ident,'start':0,'end':round(4*rate/12),'triggerStatus':'pending-source-button-timeline-binding'}
record={'sourceSha256':clock['sourceSha256'],'fixed':fixed,'wrong':wrong,'short':short,'policy':['All windows reference prepared full PCM; no encoded MP3 slicing.','Nonzero correct/S2/S3/S4 and terminal tails retained.','Wrong feedback remains user-closed; closing cancels its audio before restoring input/revealing answer. No automatic wrong-dialog dismissal added.','Correct/reveal completion clocks remain source23/12 seconds, independently of shorter correct audio.','Short source streams are inventoried but not assigned to generic controls until exact trigger evidence is completed.','180sample main source-counter versus12fps discrepancy remains disclosed.'],'audioAccepted':False,'originalRuntimeAccepted':False}
outputs={A/'native-audio-windows-v1.json':json.dumps(record,indent=2)+'\n',R/'packages/demos/src/generated/nms-l02-p048-audio-windows-v1.ts':'// Generated by scripts/generate-nms-l02-p048-audio-windows-v1.py; do not edit.\nexport const P048_FIXED_WINDOWS='+json.dumps(fixed,separators=(',',':'))+' as const;\nexport const P048_WRONG_WINDOWS='+json.dumps(wrong,separators=(',',':'))+' as const;\n'}
for p,text in outputs.items():
 if '--check' in sys.argv:assert p.read_text()==text
 else:p.write_text(text)
print(json.dumps({'fixed':fixed,'wrong':wrong}))
